const icons={ 'chevron-left':'m11 5-6 6 6 6','chevron-right':'m7 5 6 6-6 6','chevron-down':'m4 7 5 5 5-5',plus:'M9 3v12M3 9h12',more:'M9 3h.01M9 9h.01M9 15h.01',close:'m4 4 10 10M14 4 4 14',download:'M9 2v9m-4-4 4 4 4-4M3 12v4h12v-4',save:'M3 2h10l3 3v11H2V2h1M5 2v5h7V2M5 16v-6h8v6',print:'M5 6V2h8v4M5 13H2V6h14v7h-3M5 10h8v6H5z',settings:'m7 2 4 0 1 3 3 1 1 4-2 2-1 3-4 1-2-2-3-1-1-4 2-2z M11.5 9a2.5 2.5 0 1 1-5 0 2.5 2.5 0 1 1 5 0',grip:'M6 4h.01M12 4h.01M6 9h.01M12 9h.01M6 14h.01M12 14h.01',mouse:'M9 2a5 5 0 0 1 5 5v4a5 5 0 0 1-10 0V7a5 5 0 0 1 5-5zM9 2v5',clock:'M9 2a7 7 0 1 0 0 14A7 7 0 1 0 9 2M9 5v4l3 2',edit:'m11 3 3 3M3 11l9-9 4 4-9 9-5 1z',trash:'M3 5h12M6 5V2h6v3M5 5l1 11h6l1-11M8 8v5M10 8v5'};
const icon=name=>`<svg viewBox="0 0 18 18" aria-hidden="true"><path d="${icons[name]||icons.plus}"/></svg>`;
function hydrate(root=document){root.querySelectorAll('[data-icon]').forEach(e=>{e.insertAdjacentHTML('afterbegin',icon(e.dataset.icon));e.removeAttribute('data-icon')})}
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tasks=[{id:'prep',name:'Vorbereitung',short:'Vorbereitung',color:'#c482b9'},{id:'admin',name:'Admin',short:'Admin',color:'#dba8c4'},{id:'open',name:'Offener Bereich',short:'Offener Bereich',color:'#c5cdd7'},{id:'project',name:'Projekte',short:'Medienwerkstatt',color:'#85b9e2'},{id:'homework',name:'Hausaufgabenhilfe',short:'Hausaufgabenhilfe',color:'#e6b078'},{id:'holiday',name:'Ferienprogramm',short:'Ferienprogramm',color:'#ad95df'},{id:'planning',name:'Planung',short:'Planung',color:'#8cbea7'}];
const task=id=>tasks.find(t=>t.id===id)||tasks[2];
const initialPeople=[{id:'kayla',name:'Kayla',start:8,end:16,color:'#c482b9'},{id:'niko',name:'Niko',start:10,end:18,color:'#85b9e2'},{id:'lea',name:'Lea',start:13,end:20,color:'#8cbea7'},{id:'sam',name:'Sam',start:9,end:15,color:'#e6b078'}];
const todayKey=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const parseDate=s=>new Date(s+'T12:00:00');
const dateKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const addDays=(d,n)=>{const v=new Date(d);v.setDate(v.getDate()+n);return v};
const monday=d=>addDays(d,-((d.getDay()+6)%7));
const uid=()=>crypto.randomUUID();
const fmtTime=n=>`${String(Math.floor(n)).padStart(2,'0')}:${String(Math.round((n%1)*60)).padStart(2,'0')}`;
const hours=n=>new Intl.NumberFormat('de-DE',{maximumFractionDigits:2}).format(n)+' h';
const toHour=s=>{const [h,m]=s.split(':').map(Number);return h+m/60};
function seed(){const base=monday(parseDate(todayKey()));const shifts=[];const put=(p,d,start,segments)=>shifts.push({id:uid(),person:p,date:dateKey(addDays(base,d)),start,segments:segments.map(([type,duration,label])=>({type,duration,label:label||''}))});put('kayla',0,8,[['prep',2],['admin',1],['open',5]]);put('kayla',1,8,[['prep',2],['open',6]]);put('kayla',2,10,[['holiday',6,'Mädchentreff']]);put('kayla',3,8,[['admin',3],['open',5]]);put('kayla',4,10,[['planning',2,'Team-Meeting'],['open',4]]);put('niko',0,10,[['project',6],['admin',2]]);put('niko',1,10,[['project',4],['open',4]]);put('niko',2,10,[['project',8]]);put('niko',3,10,[['prep',2],['project',6]]);put('niko',4,10,[['planning',2,'Team-Meeting'],['project',4]]);put('lea',0,13,[['planning',3],['open',4]]);put('lea',1,13,[['homework',3],['open',4]]);put('lea',2,10,[['open',8]]);put('lea',3,13,[['planning',3,'Jugendforum'],['open',4]]);put('lea',4,10,[['planning',2,'Team-Meeting'],['open',4]]);put('sam',0,9,[['homework',5],['admin',1]]);put('sam',1,9,[['admin',2],['open',4]]);put('sam',3,9,[['holiday',6]]);put('sam',4,10,[['planning',2,'Team-Meeting'],['homework',3]]);return {version:1,people:initialPeople,shifts,settings:{weekend:false}}}
let data;try{const saved=JSON.parse(localStorage.getItem('flow-plan-v1'));data=saved?.version===1&&Array.isArray(saved.people)&&Array.isArray(saved.shifts)?saved:seed()}catch{data=seed()}
let week=monday(parseDate(todayKey())),selected=null,picked=null,focusDate=null,newId=null,toastTimer,editDraft;
const duration=s=>s.segments.reduce((sum,t)=>sum+Number(t.duration),0);
function persist(){try{localStorage.setItem('flow-plan-v1',JSON.stringify(data));$('.save-status').innerHTML='<i></i> Lokal gespeichert'}catch{$('.save-status').textContent='Speichern nicht möglich';toast('Der Browser konnte deine Änderungen nicht speichern. Bitte exportiere den Plan.')}}
function toast(message,undo){clearTimeout(toastTimer);const el=$('#toast');el.innerHTML=`<span>${esc(message)}</span>${undo?'<button>Rückgängig</button>':''}`;el.hidden=false;if(undo)el.querySelector('button').onclick=()=>{undo();el.hidden=true};toastTimer=setTimeout(()=>el.hidden=true,undo?8000:4200)}
function isoWeek(d){const v=new Date(d);v.setDate(v.getDate()+3);const first=new Date(v.getFullYear(),0,4);return 1+Math.round((v-monday(first))/604800000)}
function renderDock(){const tokens=$('#tokens');$('#staff-count').textContent=data.people.length;tokens.innerHTML=data.people.map(p=>`<button class="token ${picked===p.id?'selected':''}" draggable="true" data-person="${p.id}" style="--person:${p.color}" aria-label="${esc(p.name)} auf einen Tag einplanen, ${fmtTime(p.start)} bis ${fmtTime(p.end)}"><span class="dot"></span><strong>${esc(p.name)}</strong><time>${fmtTime(p.start)}–${fmtTime(p.end)}</time></button>`).join('');tokens.querySelectorAll('.token').forEach(el=>{el.ondragstart=e=>{e.dataTransfer.setData('text/plain',el.dataset.person);e.dataTransfer.effectAllowed='copy';picked=el.dataset.person;$('#instruction').textContent='Auf einem Tag loslassen – die Sollzeit wird automatisch übernommen.'};el.ondragend=()=>{picked=null;renderDock();resetInstruction();document.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'))};el.onclick=()=>{picked=picked===el.dataset.person?null:el.dataset.person;renderDock();renderTimeline();$('#instruction').textContent=picked?'Wähle einen Tag. Mit Escape brichst du ab.':'Ziehe eine Person auf einen Tag, um eine Schicht zu planen.'}})}
function resetInstruction(){$('#instruction').textContent='Ziehe eine Person auf einen Tag, um eine Schicht zu planen.'}
function renderTimeline(){const count=data.settings.weekend?7:5;const dates=focusDate?[parseDate(focusDate)]:Array.from({length:count},(_,i)=>addDays(week,i));const last=addDays(week,6);const monthFormat={month:'long'};$('#date-range').textContent=week.getMonth()===last.getMonth()?`${week.getDate()}. – ${last.getDate()}. ${last.toLocaleDateString('de-DE',monthFormat)} ${last.getFullYear()}`:`${week.toLocaleDateString('de-DE',{day:'numeric',month:'short'})} – ${last.toLocaleDateString('de-DE',{day:'numeric',month:'short',year:'numeric'})}`;$('#week-number').textContent='KW '+isoWeek(week);$('.board').classList.toggle('week-focus',!!focusDate);const grid=$('#timeline');grid.style.setProperty('--days',dates.length);grid.style.setProperty('--rows',data.people.length);let html=`<div class="grid-corner">DEIN TEAM</div>`;dates.forEach(d=>{const key=dateKey(d),current=key===todayKey();html+=`<button class="day-head ${current?'current':''}" data-date="${key}" title="${focusDate?'Zur Wochenansicht':'Tag vergrößern'}"><span class="day-title"><span class="day-name">${d.toLocaleDateString('de-DE',{weekday:'long'})}</span><span class="day-date">${current?'<i class="today-dot"></i>':''}${d.toLocaleDateString('de-DE',{day:'2-digit',month:'2-digit'})}</span></span><span class="hours"><span>08</span><span>10</span><span>12</span><span>14</span><span>16</span><span>18</span><span>20</span></span></button>`});data.people.forEach(p=>{html+=`<div class="person-name">${esc(p.name)}</div>`;dates.forEach(d=>{const key=dateKey(d),s=data.shifts.find(s=>s.person===p.id&&s.date===key);html+=`<div class="day-cell ${key===todayKey()?'current':''} ${d.getDay()===0||d.getDay()===6?'weekend':''} ${picked?'pickable':''}" data-date="${key}" data-person="${p.id}" aria-label="${esc(p.name)}, ${d.toLocaleDateString('de-DE')}" ${!s?'tabindex="0" role="button"':''}>`;if(s){html+=`<button class="shift ${s.id===selected?'active':''} ${s.id===newId?'new':''}" data-shift="${s.id}" style="--start:${(s.start-8)/12};--duration:${duration(s)/12}" aria-label="${esc(p.name)}, ${d.toLocaleDateString('de-DE')}, ${fmtTime(s.start)} bis ${fmtTime(s.start+duration(s))}: ${esc(s.segments.map(t=>t.label||task(t.type).name).join(', '))}"><time class="shift-time">${fmtTime(s.start)} – ${fmtTime(s.start+duration(s))}</time>${s.segments.map(t=>`<span class="segment" style="--segment:${task(t.type).color};--length:${t.duration}" title="${esc(t.label||task(t.type).name)} · ${hours(t.duration)}"><b>${esc(t.label||task(t.type).short)}</b>${t.duration>=4?`<small>${t.type==='project'?'Gemeinsam gestalten':t.type==='open'?'Zeit für Begegnung':hours(t.duration)}</small>`:''}</span>`).join('')}</button>`}else{html+='<span class="empty-label">Noch Raum für Neues</span><span class="drop-hint">+ Einplanen</span>'}html+='</div>'})});html+=`<div class="add-row"><button id="add-row-person" aria-label="Person hinzufügen">${icon('plus')}<span>Person</span></button></div>`+dates.map(()=>'<div class="empty-bottom"></div>').join('');grid.innerHTML=html;grid.querySelectorAll('.day-head').forEach(b=>b.onclick=()=>{focusDate=focusDate?null:b.dataset.date;renderTimeline()});grid.querySelectorAll('[data-shift]').forEach(b=>b.onclick=e=>{e.stopPropagation();selectShift(b.dataset.shift)});grid.querySelectorAll('.day-cell').forEach(cell=>{cell.ondragover=e=>{e.preventDefault();e.dataTransfer.dropEffect='copy';cell.classList.add('drag-over')};cell.ondragleave=()=>cell.classList.remove('drag-over');cell.ondrop=e=>{e.preventDefault();cell.classList.remove('drag-over');const p=e.dataTransfer.getData('text/plain');if(data.people.some(v=>v.id===p))createShift(p,cell.dataset.date)};cell.onclick=()=>{if(picked)createShift(picked,cell.dataset.date)};cell.onkeydown=e=>{if(e.target===cell&&(e.key==='Enter'||e.key===' ')){e.preventDefault();createShift(picked||cell.dataset.person,cell.dataset.date)}};cell.ondblclick=e=>{if(!e.target.closest('.shift'))createShift(cell.dataset.person,cell.dataset.date)}});$('#add-row-person').onclick=openPerson;const inWeek=data.shifts.filter(s=>s.date>=dateKey(week)&&s.date<=dateKey(last));$('#week-summary').textContent=`${inWeek.length} Schichten · ${hours(inWeek.reduce((sum,s)=>sum+duration(s),0))} gemeinsam`;newId=null}
function createShift(person,date){const exists=data.shifts.find(s=>s.person===person&&s.date===date);if(exists){picked=null;renderDock();resetInstruction();selectShift(exists.id);toast('Für diesen Tag ist bereits eine Schicht geplant.');return}const p=data.people.find(p=>p.id===person);if(!p)return;const s={id:uid(),person,date,start:p.start,segments:[{type:'open',duration:p.end-p.start,label:''}]};data.shifts.push(s);newId=s.id;picked=null;persist();renderDock();renderTimeline();resetInstruction();toast(`${p.name} eingeplant · ${fmtTime(p.start)}–${fmtTime(p.end)}`,()=>{data.shifts=data.shifts.filter(x=>x.id!==s.id);if(selected===s.id)closePanel();persist();renderTimeline()})}
function selectShift(id){selected=id;renderTimeline();renderPanel()}
function closePanel(){selected=null;$('#detail').hidden=true;renderTimeline()}
function renderPanel(){const panel=$('#detail'),s=data.shifts.find(s=>s.id===selected);if(!s){panel.hidden=true;return}const p=data.people.find(p=>p.id===s.person),total=duration(s),target=p.end-p.start;let cursor=s.start;panel.hidden=false;panel.innerHTML=`<div class="panel-top"><span class="eyebrow">DEINE SCHICHT</span><button class="icon-button" id="close-panel" aria-label="Detailpanel schließen">${icon('close')}</button></div><h2>${esc(p.name)}</h2><div class="detail-date">${parseDate(s.date).toLocaleDateString('de-DE',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</div><div class="detail-time">${icon('clock')} ${fmtTime(s.start)} – ${fmtTime(s.start+total)} <small>${hours(total)}</small></div><div class="detail-separator"></div><span class="eyebrow">VERANTWORTUNG & AUFGABEN</span><div class="task-list">${s.segments.map(t=>{const start=cursor;cursor+=Number(t.duration);return `<div class="task-item"><i class="legend-dot" style="--segment:${task(t.type).color}"></i><div><strong>${esc(t.label||task(t.type).name)}</strong><time>${fmtTime(start)} – ${fmtTime(cursor)}</time></div></div>`}).join('')}</div><div class="detail-separator"></div><div class="stats"><div><span>Sollstunden</span><b>${hours(target)}</b></div><div><span>Geplante Stunden</span><b>${hours(total)}</b></div><div><span>Überstunden</span><b class="${total>target?'positive':''}">${hours(Math.max(0,total-target))}</b></div>${total<target?`<div><span>Noch unverplant</span><b>${hours(target-total)}</b></div>`:''}</div><div class="panel-actions"><button id="edit-shift" class="primary-button">${icon('edit')} Bearbeiten</button><button id="delete-shift" class="delete-button" aria-label="Schicht löschen" title="Schicht löschen">${icon('trash')}</button></div><p class="panel-note">Eine Schicht. Geteilte Verantwortung.<br>Aufgaben bleiben Teil des gemeinsamen Ganzen.</p>`;$('#close-panel').onclick=closePanel;$('#edit-shift').onclick=()=>openEdit(s);$('#delete-shift').onclick=()=>{data.shifts=data.shifts.filter(x=>x.id!==s.id);persist();closePanel();toast('Schicht gelöscht.',()=>{data.shifts.push(s);persist();selectShift(s.id)})}}
function openModal(html){$('#modal-content').innerHTML=html;$('#modal').showModal();$('#modal-close').onclick=()=>$('#modal').close();hydrate($('#modal'))}
function modalTop(title){return `<div class="modal-top"><h2>${title}</h2><button type="button" class="icon-button" id="modal-close" aria-label="Schließen">${icon('close')}</button></div>`}
function openPerson(){openModal(`${modalTop('Ein Platz im Team')}<form id="person-form"><label class="full-field"><span class="field-label">Name</span><input name="name" placeholder="Wie heißt die Person?" maxlength="24" required autocomplete="off"></label><div class="form-row"><label><span class="field-label">Arbeitsbeginn</span><input name="start" type="time" value="09:00" min="08:00" max="19:45" step="900" required></label><label><span class="field-label">Arbeitsende</span><input name="end" type="time" value="17:00" min="08:15" max="20:00" step="900" required></label></div><label class="full-field"><span class="field-label">Farbe im Dock</span><input name="color" type="color" value="#ad95df"></label><p class="modal-note">Beim Einplanen übernehmen wir diese Standardarbeitszeit automatisch.</p><p class="form-error" id="person-error"></p><div class="form-actions"><button type="button" class="secondary-button" id="cancel-person">Abbrechen</button><button class="primary-button" type="submit">Zum Team hinzufügen</button></div></form>`);$('#cancel-person').onclick=()=>$('#modal').close();$('#person-form').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target),name=String(form.get('name')).trim(),start=toHour(form.get('start')),end=toHour(form.get('end'));if(!name||end<=start||start<8||end>20){$('#person-error').textContent='Bitte wähle einen Namen und eine Arbeitszeit zwischen 08:00 und 20:00 Uhr.';return}data.people.push({id:uid(),name,start,end,color:form.get('color')});persist();renderDock();renderTimeline();$('#modal').close();toast(`${name} ist jetzt im Team.`)}}
function openEdit(s){editDraft=structuredClone(s);openModal(`${modalTop('Schicht gestalten')}<form id="edit-form"><div class="form-row"><label><span class="field-label">Datum</span><input id="edit-date" type="date" value="${s.date}" required></label><label><span class="field-label">Beginn</span><input id="edit-start" type="time" value="${fmtTime(s.start)}" min="08:00" max="19:45" step="900" required></label></div><div class="field-label">Aufgaben <span style="float:right;margin-right:32px">Stunden</span></div><div id="edit-tasks"></div><button class="subtle-button" type="button" id="add-task">${icon('plus')} Aufgabe hinzufügen</button><div class="settings-row"><span>Geplante Zeit</span><b id="edit-total"></b></div><p class="form-error" id="edit-error"></p><div class="form-actions"><button type="button" class="secondary-button" id="cancel-edit">Abbrechen</button><button class="primary-button" type="submit">Änderungen speichern</button></div></form>`);renderEditTasks();$('#cancel-edit').onclick=()=>$('#modal').close();$('#add-task').onclick=()=>{editDraft.segments.push({type:'prep',duration:1,label:''});renderEditTasks()};$('#edit-form').onsubmit=e=>{e.preventDefault();editDraft.start=toHour($('#edit-start').value);editDraft.date=$('#edit-date').value;const total=duration(editDraft);if(editDraft.segments.length===0||editDraft.segments.some(t=>!Number.isFinite(t.duration)||t.duration<=0)||editDraft.start<8||editDraft.start+total>20){$('#edit-error').textContent='Die Schicht braucht mindestens eine Aufgabe und muss zwischen 08:00 und 20:00 Uhr liegen.';return}if(data.shifts.some(x=>x.id!==editDraft.id&&x.person===editDraft.person&&x.date===editDraft.date)){$('#edit-error').textContent='An diesem Tag besteht bereits eine Schicht für diese Person.';return}data.shifts[data.shifts.findIndex(x=>x.id===s.id)]=structuredClone(editDraft);persist();$('#modal').close();renderTimeline();renderPanel();toast('Schicht aktualisiert.')}}
function renderEditTasks(){$('#edit-tasks').innerHTML=editDraft.segments.map((t,i)=>`<div class="edit-task"><select data-i="${i}" aria-label="Aufgabe ${i+1}">${tasks.map(k=>`<option value="${k.id}" ${k.id===t.type?'selected':''}>${esc(t.label&&k.id===t.type?t.label:k.name)}</option>`).join('')}</select><input data-i="${i}" type="number" min="0.25" max="12" step="0.25" value="${t.duration}" required aria-label="Stunden für Aufgabe ${i+1}"><button class="icon-button" style="width:25px" type="button" data-remove="${i}" aria-label="Aufgabe ${i+1} entfernen">${icon('close')}</button></div>`).join('');$('#edit-total').textContent=hours(duration(editDraft));$('#edit-tasks').querySelectorAll('select').forEach(el=>el.onchange=()=>{const t=editDraft.segments[+el.dataset.i];t.type=el.value;t.label=''});$('#edit-tasks').querySelectorAll('input').forEach(el=>el.oninput=()=>{editDraft.segments[+el.dataset.i].duration=+el.value;$('#edit-total').textContent=hours(duration(editDraft))});$('#edit-tasks').querySelectorAll('[data-remove]').forEach(el=>el.onclick=()=>{editDraft.segments.splice(+el.dataset.remove,1);renderEditTasks()})}
function openSettings(){openModal(`${modalTop('Dein Planungsraum')}<form id="settings-form"><label class="settings-row"><span>Wochenende anzeigen<small>Samstag und Sonntag mitplanen</small></span><input id="weekend" type="checkbox" ${data.settings.weekend?'checked':''}></label><p class="modal-note" style="margin-top:23px">Flow! speichert deinen Plan in diesem Browser. Über das Menü kannst du eine Kopie als JSON oder die aktuelle Woche als CSV exportieren.</p><p class="modal-note">Tipp: Klicke auf einen Tagesnamen, um mehr Platz für seine Aufgaben zu bekommen. Ein erneuter Klick zeigt die ganze Woche.</p><div class="form-actions"><button class="primary-button" type="submit">Übernehmen</button></div></form>`);$('#settings-form').onsubmit=e=>{e.preventDefault();data.settings.weekend=$('#weekend').checked;focusDate=null;persist();renderTimeline();$('#modal').close()}}
function download(content,type,name){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCSV(){const rows=[['Name','Datum','Beginn','Ende','Aufgabe','Stunden']];data.shifts.filter(s=>s.date>=dateKey(week)&&s.date<=dateKey(addDays(week,6))).sort((a,b)=>a.date.localeCompare(b.date)).forEach(s=>{let cursor=s.start;s.segments.forEach(t=>{rows.push([data.people.find(p=>p.id===s.person).name,s.date,fmtTime(cursor),fmtTime(cursor+t.duration),t.label||task(t.type).name,String(t.duration).replace('.',',')]);cursor+=t.duration})});const csv=rows.map(r=>r.map(v=>{let str=String(v);if(/^[=+\-@]/.test(str))str="'"+str;return '"'+str.replaceAll('"','""')+'"'}).join(';')).join('\r\n');download('\ufeff'+csv,'text/csv;charset=utf-8',`Flow-Woche-${dateKey(week)}.csv`);toast('Die aktuelle Woche wurde exportiert.')}
$('#prev').onclick=()=>changeWeek(-7);$('#next').onclick=()=>changeWeek(7);function changeWeek(n){week=addDays(week,n);focusDate=null;closePanel()}
$('#today').onclick=()=>{week=monday(parseDate(todayKey()));focusDate=null;closePanel()};$('#dock-toggle').onclick=()=>{const collapsed=$('.dock').classList.toggle('collapsed');$('#dock-toggle').setAttribute('aria-expanded',String(!collapsed))};$('#add-person').onclick=openPerson;
function closeMenu(){$('#menu').hidden=true;$('#more').setAttribute('aria-expanded','false')}
$('#more').onclick=()=>{const hidden=!$('#menu').hidden;$('#menu').hidden=hidden;$('#more').setAttribute('aria-expanded',String(!hidden))};document.addEventListener('click',e=>{if(!e.target.closest('.menu-wrap'))closeMenu()});$('#menu').querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{closeMenu();({export:exportCSV,backup:()=>{download(JSON.stringify(data,null,2),'application/json',`Flow-Plan-${todayKey()}.json`);toast('Dein Plan wurde als JSON gespeichert.')},print:()=>window.print(),settings:openSettings})[b.dataset.action]()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){picked=null;renderDock();renderTimeline();resetInstruction();closeMenu();if(!$('#modal').open)closePanel()}});$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
$('#legend').innerHTML=tasks.map(t=>`<span class="legend-item"><i class="legend-dot" style="--segment:${t.color}"></i>${t.name}</span>`).join('');hydrate();renderDock();renderTimeline();persist();
